import CoreText
import CoreGraphics
import Foundation

let fontCandidates = ["HiraginoSans-W7", "HiraginoSans-W6", "HiraginoSans-W5", "AvenirNext-Bold", "AvenirNext-Heavy", "SFNSRounded-Bold"]
for name in fontCandidates {
    let font = CTFontCreateWithName(name as CFString, 100, nil)
    let ps = CTFontCopyPostScriptName(font) as String
    let full = CTFontCopyFullName(font) as String
    print("asked=\(name) ps=\(ps) full=\(full)")
}

func svgPath(_ path: CGPath, flipHeight: CGFloat) -> String {
    var commands: [String] = []
    path.applyWithBlock { elemPtr in
        let elem = elemPtr.pointee
        func fmt(_ p: CGPoint) -> String {
            let y = flipHeight - p.y
            return String(format: "%.2f %.2f", p.x, y)
        }
        switch elem.type {
        case .moveToPoint:
            commands.append("M " + fmt(elem.points[0]))
        case .addLineToPoint:
            commands.append("L " + fmt(elem.points[0]))
        case .addQuadCurveToPoint:
            commands.append("Q " + fmt(elem.points[0]) + " " + fmt(elem.points[1]))
        case .addCurveToPoint:
            commands.append("C " + fmt(elem.points[0]) + " " + fmt(elem.points[1]) + " " + fmt(elem.points[2]))
        case .closeSubpath:
            commands.append("Z")
        @unknown default:
            break
        }
    }
    return commands.joined(separator: " ")
}

let font = CTFontCreateWithName("HiraginoSans-W7" as CFString, 100, nil)
let sample = "ラーメン"
var xCursor: CGFloat = 0
for ch in sample {
    let s = String(ch)
    let utf16 = Array(s.utf16)
    var glyphs = [CGGlyph](repeating: 0, count: utf16.count)
    var chars = utf16
    let ok = CTFontGetGlyphsForCharacters(font, &chars, &glyphs, utf16.count)
    var advance = CGSize.zero
    CTFontGetAdvancesForGlyphs(font, .horizontal, glyphs, &advance, 1)
    if let path = CTFontCreatePathForGlyph(font, glyphs[0], nil) {
        let box = CTFontGetBoundingRectsForGlyphs(font, .horizontal, glyphs, nil, 1)
        print("CHAR \(ch) ok=\(ok) adv=\(advance.width) box=\(box)")
        print(svgPath(path, flipHeight: 100))
        print("---")
    } else {
        print("NO PATH for \(ch) ok=\(ok)")
    }
}
