            break
        }
    }
    return commands.joined(separator: " ")
}

func dump(fontName: String, size: CGFloat, chars: String) {
    let font = CTFontCreateWithName(fontName as CFString, size, nil)
    let baseline = size
    print("FONT \(fontName) size \(size)")
    for ch in chars {
        let s = String(ch)
        var glyphs = [CGGlyph](repeating: 0, count: 1)
        var utf = Array(s.utf16)
        let ok = CTFontGetGlyphsForCharacters(font, &utf, &glyphs, 1)
        guard ok, let path = CTFontCreatePathForGlyph(font, glyphs[0], nil) else {
            print("MISSING \(ch)")
            continue
        }
        var adv = CGSize.zero
        CTFontGetAdvancesForGlyphs(font, .horizontal, glyphs, &adv, 1)
        var box = CGRect.zero
        CTFontGetBoundingRectsForGlyphs(font, .horizontal, glyphs, &box, 1)
        // svg bbox with baseline
        let x0 = box.minX
        let y0 = baseline - box.maxY
        let x1 = box.maxX
        let y1 = baseline - box.minY
        let d = svgPath(path, baseline: baseline)
        let esc = d.replacingOccurrences(of: "\\", with: "\\\\").replacingOccurrences(of: "\"", with: "\\\"")
        print("    \"\(ch)\": {\"adv\": \(String(format: "%.2f", adv.width)), \"box\": (\(String(format: "%.2f", x0)), \(String(format: "%.2f", y0)), \(String(format: "%.2f", x1)), \(String(format: "%.2f", y1))), \"d\": \"\(esc)\"},")
    }
}

