import Cocoa
import WebKit

final class Snap: NSObject, WKNavigationDelegate {
    let web: WKWebView
    let out: String
    init(out: String) {
        self.out = out
        let config = WKWebViewConfiguration()
        web = WKWebView(frame: NSRect(x: 0, y: 0, width: 1600, height: 1120), configuration: config)
        super.init()
        web.navigationDelegate = self
        let win = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 1600, height: 1120),
                           styleMask: [.borderless], backing: .buffered, defer: false)
        win.contentView = web
        win.makeKeyAndOrderFront(nil)
    }
    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            let cfg = WKSnapshotConfiguration()
            cfg.rect = CGRect(x: 0, y: 0, width: 1600, height: 1120)
            self.web.takeSnapshot(with: cfg) { image, error in
                if let image = image, let tiff = image.tiffRepresentation,
                   let rep = NSBitmapImageRep(data: tiff),
                   let png = rep.representation(using: .png, properties: [:]) {
                    do {
                        try png.write(to: URL(fileURLWithPath: self.out))
                        print("WROTE \(self.out) \(image.size)")
                    } catch {
                        print("WRITE FAIL \(error)")
                    }
                } else {
                    print("SNAP FAIL \(error?.localizedDescription ?? "nil")")
                }
                NSApp.terminate(nil)
            }
        }
    }
    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) {
        print("NAV FAIL \(error)")
        NSApp.terminate(nil)
    }
    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) {
        print("PROV FAIL \(error)")
        NSApp.terminate(nil)
    }
}

let out = CommandLine.arguments.count > 2 ? CommandLine.arguments[2] : "/tmp/exact.png"
