let url = URL(fileURLWithPath: path)
snap.web.loadFileURL(url, allowingReadAccessTo: url.deletingLastPathComponent())
DispatchQueue.main.asyncAfter(deadline: .now() + 8) {
    print("TIMEOUT")
    NSApp.terminate(nil)
}
app.run()
